1	/**
2	 * inject-sub-results.ts — Replace the last tool message in a session with
3	 * aggregated sub-issue completion results, so the atomaton sees a
4	 * summary of what happened when it's re-invoked for final aggregation.
5	 * The one canonical implementation (was inject_sub_results.ts), called
6	 * directly by aggregate_sub_issues.ts -- no more subprocess spawn.
7	 */
8	import { gh } from "../../adapters/github/gh.ts";
9	import type { GhPrSummary } from "../github/wire-types.ts";
10	import type { Session, SessionMessage } from "../../domain/work/session.ts";
11	
12	// No `export type { Session, SessionMessage }` here.
13	//
14	// Eleven files import `Session` from `domain/work/session.ts`; exactly one used to get
15	// it through this re-export, which made a second route to the same type. See
16	// `config.ts`, which argues the same point about `getDeclaredSecrets`: the next
17	// caller finds whichever route it meets first, and then the two exist forever.
18	
19	function findLastToolIndex(messages: SessionMessage[]): number | null {
20	  for (let i = messages.length - 1; i >= 0; i--) {
21	    if (messages[i]?.role === "tool") return i;
22	  }
23	  return null;
24	}
25	
26	export function gatherSubResults(repo: string, subIssues: number[]): string {
27	  const lines: string[] = ["All sub-issues have been completed.", "", "## Sub-issue Results", ""];
28	
29	  for (const num of subIssues) {
30	    let title = "Unknown";
31	    // Not "closed". This block feeds the atomaton's final report, whose whole
32	    // job is to state what happened, and a sub-issue whose state could not be
33	    // read is exactly the one thing that report must not assert. One rate-limited
34	    // lookup used to turn into "Status: closed" for work still in progress.
35	    let state = "could not be read";
36	
37	    try {
38	      const { code, stdout } = gh("issue", "view", String(num), "--repo", repo, "--json", "title,state,closedAt");
39	      if (code === 0 && stdout) {
40	        const info = JSON.parse(stdout) as { title?: string; state?: string };
41	        title = info.title ?? "Unknown";
42	        state = info.state ?? "could not be read";
43	      }
44	    } catch {
45	      // keep defaults
46	    }
47	
48	    const linkedPrs: string[] = [];
49	    // Tracked separately from an empty result, because "none found" and "could
50	    // not look" read identically once they reach the report and only one of them
51	    // is a fact.
52	    let prLookupFailed = false;
53	    for (const state_ of ["merged", "open"] as const) {
54	      try {
55	        const { code, stdout } = gh("pr", "list", "--repo", repo, "--state", state_, "--search", `#${num} in:body`, "--json", "number,title,url");
56	        if (code === 0 && stdout) {
57	          const prs = JSON.parse(stdout) as GhPrSummary[];
58	          for (const pr of prs) {
59	            linkedPrs.push(`- PR #${pr.number}: ${pr.title} (${pr.url})`);
60	          }
61	        } else {
62	          prLookupFailed = true;
63	        }
64	      } catch {
65	        prLookupFailed = true;
66	      }
67	    }
68	
69	    lines.push(`### #${num}: ${title}`);
70	    lines.push(`Status: ${state}`);
71	    if (linkedPrs.length) {
72	      lines.push("Linked PRs:");
73	      lines.push(...linkedPrs);
74	    } else if (prLookupFailed) {
75	      lines.push("Linked PRs could not be read.");
76	    } else {
77	      lines.push("No linked PRs found.");
78	    }
79	    lines.push("");
80	  }
81	
82	  lines.push("---");
83	  lines.push("All sub-issues are complete. Please review the results and aggregate them into a final summary.");
84	  return lines.join("\n");
85	}
86	
87	/**
88	 * Put `summary` where the atomaton will read it: over the last tool message,
89	 * or appended as a user message when the session has none.
90	 *
91	 * Takes the text rather than fetching it. The doc comment here used to say
92	 * "Pure transform: returns an updated copy-in-place" -- which is two claims and
93	 * both were wrong. It was not pure: it called `gatherSubResults`, up to three
94	 * `gh` calls per sub-issue. And it is not a copy: it mutates `session.messages`
95	 * in place and returns the same object, which "copy-in-place" says in one
96	 * self-contradictory breath.
97	 *
98	 * The cost was that this rule -- find the last tool message, replace it, append
99	 * when there is none -- could not be tested without a fake `gh` on PATH. It is a
100	 * decision about a data structure and now reads like one.
101	 */
102	export function injectSummary(session: Session, summary: string): Session {
103	  const messages = session.messages ?? [];
104	  const lastToolIdx = findLastToolIndex(messages);
105	
106	  if (lastToolIdx === null) {
107	    console.error("No tool message found in session. Appending as user message.");
108	    messages.push({ role: "user", content: summary });
109	  } else {
110	    messages[lastToolIdx]!.content = summary;
111	  }
112	
113	  session.messages = messages;
114	  return session;
115	}
