1	#!/usr/bin/env bun
2	/**
3	 * aggregate_sub_issues.ts — Called after a PR merges and its linked
4	 * sub-issue's atomaton parent is known. If any sibling sub-issues are
5	 * still open, just posts a progress comment. Once all siblings are done,
6	 * aggregates their results into the atomaton's session (stored on the
7	 * orphan `atomaton-data` branch) and re-dispatches the atomaton.
8	 *
9	 * Thin CLI wrapper around lib/aggregation.ts's shared dispatch gate -- see that
10	 * module's doc comment for the other two callers of the same gate and for the
11	 * race between them.
12	 *
13	 * Usage:
14	 *   aggregate_sub_issues.ts --repo OWNER/REPO --parent N --closed-num N
15	 */
16	import { parseArgs } from "node:util";
17	import { gh } from "../../adapters/github/gh.ts";
18	import { defineScript } from "./lib/script-ref.ts";
19	import { describeGateResult, dispatchOrchestratorIfReady, needsAttention } from "../../app/aggregation.ts";
20	import { gatherSubResults, injectSummary } from "../../adapters/atoma/inject-sub-results.ts";
21	import type { Session } from "../../domain/work/session.ts";
22	import { issueLinks } from "../../adapters/github/issue-links.ts";
23	import { mostRecentAgentOn } from "../../adapters/github/agent-on-issue.ts";
24	import { restoreSession, saveSession, sessionTargetPath } from "./lib/atomaton-data.ts";
25	
26	export interface AggregateSubIssuesArgs {
27	  repo: string;
28	  parent: string | number;
29	  "closed-num": string | number;
30	}
31	
32	export const ref = defineScript<AggregateSubIssuesArgs>(import.meta.url);
33	
34	/**
35	 * Every sub-issue linked to `parent`, open or closed.
36	 *
37	 * GitHub's own sub-issue links, which is where every other reader of this
38	 * relationship now looks. It used to search for `atomaton:parent=N in:body` and then
39	 * re-check each hit with `PARENT_TAG.read`, because GitHub's issue search tokenizes
40	 * and returned `atomaton:parent=50` for a query of `5` — a prefilter that needed a
41	 * predicate behind it, and before that predicate existed this collected every
42	 * sub-issue of a numeric range and fed their results into the wrong atomaton's
43	 * session. A link has no such failure mode: it is an edge, not a string.
44	 *
45	 * Throws when the links could not be read. Aggregation injects these results into
46	 * the atomaton's session, and an empty list read as "no sub-issues" would
47	 * re-invoke it with none of the work it is supposed to be summarising.
48	 */
49	function linkedSubIssues(repo: string, parent: number): number[] {
50	  const links = issueLinks(repo, parent);
51	  if (links.unavailable) {
52	    throw new Error(`could not list sub-issues of #${parent}: ${links.unavailable}`);
53	  }
54	  return links.children.map((child) => child.number);
55	}
56	
57	/**
58	 * Injects every linked sub-issue's result into the parent's persisted session on
59	 * the `atomaton-data` branch.
60	 *
61	 * Reads and writes through lib/atomaton-data.ts rather than driving git here. That
62	 * module's `saveSession` already owns the part that is easy to get wrong -- it
63	 * creates the branch if absent, holds the push-retry loop for the races that are
64	 * expected when sibling agents finish together, and does all of it in a
65	 * throwaway worktree so the job's own checkout is untouched. This function used
66	 * to reimplement that with `git checkout -B atomaton-data` in the main checkout
67	 * (and `git rm -rf .` on the branch-missing path), which worked only because
68	 * nothing in this job reads a file afterwards.
69	 *
70	 * `agent` is the one that was working on the parent, read from the parent's own
71	 * thread. It was the literal `"atomaton"`, which meant a project that renamed
72	 * its atomaton injected the results into a session file nothing would ever
73	 * restore -- the aggregation ran, reported success, and the re-invoked agent
74	 * started with none of the work it was supposed to summarise.
75	 */
76	function injectResultsIntoParentSession(repo: string, parent: number, agent: string): void {
77	  const subIssues = linkedSubIssues(repo, parent);
78	  console.error(`Sub-issues of #${parent}: ${subIssues.join(", ") || "(none)"}`);
79	
80	  const sessionPath = sessionTargetPath("issue", parent, agent);
81	  const existing = restoreSession(sessionPath);
82	  const session: Session = existing ? (JSON.parse(existing) as Session) : { messages: [] };
83	
84	  // Composed here, where the I/O belongs: read what the sub-issues did, then
85	  // put it in the session. `injectSummary` is the half that decides where.
86	  const updated = injectSummary(session, gatherSubResults(repo, subIssues));
87	  const message = `atomaton: inject sub-issue results for parent #${parent}`;
88	  if (!saveSession(sessionPath, JSON.stringify(updated, null, 2), message)) {
89	    console.error(`::warning::Failed to save session to atomaton-data:${sessionPath} after all retries.`);
90	  }
91	}
92	
93	async function main(): Promise<void> {
94	  const { values } = parseArgs({
95	    args: Bun.argv.slice(2),
96	    options: {
97	      repo: { type: "string" },
98	      parent: { type: "string" },
99	      "closed-num": { type: "string" },
100	    },
101	  });
102	  const repo = values.repo;
103	  const parent = values.parent;
104	  const closedNum = values["closed-num"];
105	  if (!repo || !parent || !closedNum) {
106	    console.error("usage: aggregate_sub_issues.ts --repo OWNER/REPO --parent N --closed-num N");
107	    process.exit(2);
108	  }
109	
110	  console.error(`PR merged (sub-issue #${closedNum}, parent #${parent}). Checking siblings...`);
111	
112	  const result = await dispatchOrchestratorIfReady({
113	    repo,
114	    parent: Number(parent),
115	    closedNum: Number(closedNum),
116	    // We already KNOW this sub-issue's work is done (its PR just merged)
117	    // regardless of whether GitHub's live issue state reflects that yet
118	    // (native "Closes #N" auto-close is unreliable under the Actions
119	    // GITHUB_TOKEN) -- excluding it makes this check reliably correct on
120	    // its first (and normally only) run instead of depending on that timing.
121	    exclude: true,
122	    progressMessage: (remaining) => `Atomaton: Sub-task #${closedNum} completed. ${remaining} sub-task(s) still in progress.`,
123	    // The agent that was on the parent, read from the parent's own thread. The
124	    // gate reads the same name for its dispatch; this is the session file that
125	    // dispatch will restore, so the two have to agree -- and both come from the
126	    // thread rather than from a literal.
127	    beforeDispatch: () => injectResultsIntoParentSession(repo, Number(parent), mostRecentAgentOn(repo, Number(parent))),
128	  });
129	
130	  console.error(describeGateResult(result, Number(closedNum), Number(parent)));
131	  // A run that left work undone must not look green. `needsAttention` is true
132	  // only for the two outcomes nothing else will retry.
133	  if (needsAttention(result)) process.exit(1);
134	}
135	
136	if (import.meta.main) void main();
