15	export interface ConcludeIssueResult {
16	  /**
17	   * Whether this closed the issue or asked its author to.
18	   *
19	   * Both are conclusions, and the caller ends the session on either. The
20	   * distinction exists because the two leave the world differently — only a
21	   * closed issue wakes its parent — not because one of them failed. See
22	   * `domain/work/close-request.ts` for why the second is not a refusal.
23	   */
24	  outcome: "closed" | "close-requested";
25	  /**
26	   * The comment this conclusion went out as, when GitHub gave one back.
27	   *
28	   * Carried out rather than recorded here, because whether the session ends on
29	   * this call is the caller's answer — a `stalled` aggregation keeps it open
30	   * (`mcp/atomaton.ts`), and a comment recorded as the run's ending while the run
31	   * went on would put the result footer on a comment that is not the ending.
32	   * The caller records it through `recordEndingComment` on exactly the paths
33	   * where its own meta carries `session_ends`.
34	   */
35	  commentId?: string;
36	  /**
37	   * What the parent's aggregation gate did afterwards, when this closed a
38	   * sub-issue.
39	   *
40	   * Carried out rather than discarded. `request_close_issue` ends the
41	   * atomaton's session, so if the gate could not read what it needed and
42	   * refused to dispatch, nothing else is left to notice -- the parent simply
43	   * waits for a re-invocation that will never come.
44	   */
45	  aggregation?: DispatchGateResult;
46	}
47	
48	/**
49	 * Throw unless a mutation actually happened.
50	 *
51	 * The author lookup below already checks its exit code, with a comment
52	 * explaining that picking an answer on a failed read "asserts something this did
53	 * not determine". Both mutations then ignored theirs entirely, which asserts
54	 * something rather worse: `request_close_issue` is the atomaton's designated
55	 * terminal action, so it returns `outcome: "closed"`, tells the agent the issue
56	 * "has been closed automatically", and ends the session — after which nothing is
57	 * left running to notice that it is still open. `dispatchOrchestratorIfSubIssueReady`
58	 * then counts siblings against an issue that never closed.
59	 *
60	 * The close-requested half is the same shape, and worse now that it reports
61	 * success: a failed comment means the person named in it is never asked to close
62	 * anything, while the agent is told the issue is concluded and its session ends.
63	 *
64	 * Throwing reaches the agent as a tool error, which is the one moment it can
65	 * still act.
66	 */
67	function mustSucceed(result: { code: number; stdout: string; stderr: string }, what: string): void {
68	  if (result.code === 0) return;
69	  throw new Error(`Could not ${what}: ${result.stderr.trim() || result.stdout.trim() || `gh exited ${result.code}`}`);
70	}
71	
72	/**
73	 * Concludes the issue: closes an agent-opened one, asks the author to close a
74	 * person-opened one.
75	 *
76	 * Neither branch fails, and the caller ends the session on both. Who opened the
77	 * issue is this function's question to ask, not its caller's to handle — see
78	 * `domain/work/close-request.ts` for the reports that came out of answering it
79	 * the other way.
80	 */
81	export async function concludeIssue(issue: number, reason: string, summary: string): Promise<ConcludeIssueResult> {
82	  const repo = process.env.GITHUB_REPOSITORY ?? "";
83	  // The exit code decides, not just the presence of output. An unread author is
84	  // not a human author: closing the issue outright and telling a person "this was
85	  // opened directly by a human" are different acts, and picking either one on a
86	  // failed lookup asserts something this did not determine. The same question is
87	  // asked fail-loud in `mcp/github.ts` via `ghJsonOrThrow`.
88	  const { code, stdout } = gh("issue", "view", String(issue), "--repo", repo, "--json", "author");
89	  if (code !== 0) {
90	    throw new Error(
91	      `Could not read the author of issue #${issue}, so this cannot tell whether closing it is yours to do.`,
92	    );
93	  }
94	  const authorInfo = stdout ? (JSON.parse(stdout) as GhIssueAuthor) : {};
95	  // Absent field still means "treat as a person", which is the cautious half of
96	  // the pair: it hands the decision to someone rather than taking it. The rule is
97	  // `domain/work/actor.ts`'s, shared with every other reader of the same fact.
98	  const isBot = !isHumanAuthor(authorInfo.author?.is_bot);
99	
100	  let body = `Atomaton: the agent on this issue considers its work complete.\n\n**Reason:** ${reason}`;
101	  if (summary) {
102	    body += `\n\n${summary}`;
103	  }
104	
105	  if (!isBot) {
106	    // The request goes above the reason and summary, not after them. It is the
107	    // only sentence in the comment addressed to the person reading it.
108	    //
109	    // `ended: "done"` because this IS the turn ending: the run is over, the issue stays
110	    // open, and the ball is with the person who was just asked to close it. Leaving it
111	    // out left the node's last turn event as the `asked` that started the run, so the
112	    // guard read "the ball is with an agent" and DELETED the person's next comment —
113	    // which, on this path, is their agreement to close the issue. The failure notice's
114	    // half is #90's; this is the same defect here, in code written to fix #90. See
115	    // `turn-comment.ts`.
116	    const request = closeRequestComment({ notify: resolveNotify(repo, issue), body });
117	    const posted = gh("issue", "comment", String(issue), "--repo", repo, "--body", turnCommentBody({ ended: "done", audience: "person", body: request, ...endingIdentity() }));
118	    mustSucceed(posted, `comment on issue #${issue}`);
119	    // stderr, where the tool's own decisions belong. Putting it in the result is
120	    // what put it in the agent's report.
121	    console.error(`close requested: issue=#${issue} (opened by a person, left open for them)`);
122	    return { outcome: "close-requested", commentId: commentIdFromUrl(posted.stdout) };
123	  }
124	
125	  // The conclusion itself. `audience: "model"` because this is what the parent agent
126	  // reads when it aggregates what its children found — the reason and the summary are
127	  // written for that reader, and were reaching it only because an untagged comment is
128	  // included by default rather than by anybody deciding.
129	  //
130	  // `ended: "done"` for the same reason as the branch above: this run is over and the
131	  // session ends on this call. It closes the issue just below, so the thread has an
132	  // answer either way — but a close is not an event to `domain/work/thread.ts`, and the
133	  // turn's ending has to be written down rather than inferred from one.
134	  const posted = gh("issue", "comment", String(issue), "--repo", repo, "--body", turnCommentBody({ ended: "done", audience: "model", body, ...endingIdentity() }));
135	  mustSucceed(posted, `comment on issue #${issue}`);
136	  mustSucceed(gh("issue", "close", String(issue), "--repo", repo), `close issue #${issue}`);
137	  console.error(`closed: issue=#${issue} (bot-authored)`);

